<script setup>
/*
 * 定数历史：选一个版本，按「定数列表」的排版还原那一刻的谱面。
 * 数据来自 files/lvmdf/history.json（每首歌、每档难度的 [版本, 定数] 时间线）。
 */
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useOpenSong } from '../../api/openSong.js'
import { loadLevelHistory, compareVersion, valueAt } from '../../api/levelHistory.js'
import { difColor, chartCover } from '../../api/common.js'
import { setAnchorNav, clearAnchorNav } from '../../composables/useAnchorNav.js'
import { useRemScale } from '../../utils/rem.js'
import levelCard from '../../components/cards/levelCard.vue'
import ScrollTabs from '../../components/ui/ScrollTabs.vue'

useRemScale()

const openSong = useOpenSong()

const DIFFS = ['EZ', 'HD', 'IN', 'AT', 'Legacy']
const DIFF_ORDER = new Map(DIFFS.map((diff, index) => [diff, index]))

const history = ref(null)
const selectedVersion = ref('')

const versions = computed(() => history.value?.versions || [])

// 一张谱面 = 曲目 + 难度；这一版有哪几张、定数多少，都从时间线取
const charts = computed(() => {
  const data = history.value
  const version = selectedVersion.value
  if (!data || !version) return []
  const list = []
  for (const [key, song] of Object.entries(data.songs)) {
    if (compareVersion(song.added, version) > 0) continue
    // 移除版本指的是最后一次出现的版本，所以这一版正好等于移除版本时还在
    if (song.removed && compareVersion(version, song.removed) > 0) continue
    // display 为 false 的曲目不进定数表
    if (song.hidden) continue
    // 历史曲绘：按版本取第几张（-1、-2 是旧图，0 是现用图）；个别曲目每档难度另有专属曲绘
    const illVariant = valueAt(song.ill || [], version)
    // AT 谱面不是随曲目一起出的：早于它首现的那一版还没有这一档
    const atReady = !song.at || compareVersion(version, song.at) >= 0
    for (const diff of DIFFS) {
      const timeline = song.diffs[diff]
      if (!timeline) continue
      // Legacy 是 1.6.8 重做旧谱面时单独记的一档，只在那一版出现，别在之后的版本里常驻
      if (diff === 'Legacy' && compareVersion(version, timeline[0][0]) !== 0) continue
      if (diff === 'AT' && !atReady) continue
      const level = valueAt(timeline, version)
      if (!level) continue
      list.push({ key, name: song.name, diff, level, cover: chartCover(key, diff, illVariant) })
    }
  }
  return list
})

// 和定数列表一样按定数分组：同一档定数的谱面排在一起，组内按曲名、难度排
const groups = computed(() => {
  const buckets = new Map()
  for (const chart of charts.value) {
    const level = chart.level.toFixed(1)
    if (!buckets.has(level)) buckets.set(level, [])
    buckets.get(level).push(chart)
  }
  return [...buckets.entries()]
    .sort((a, b) => Number(b[0]) - Number(a[0]))
    .map(([level, items]) => ({
      level,
      charts: items.sort(
        (a, b) =>
          a.name.localeCompare(b.name, 'zh-Hans-CN') || DIFF_ORDER.get(a.diff) - DIFF_ORDER.get(b.diff)
      )
    }))
})

// 每个定数段登记成一个锚点，侧栏的「本页目录」可以直接跳段（和定数列表一致）
watch(
  groups,
  (list) => {
    if (!list.length) {
      clearAnchorNav()
      return
    }
    // 一级是整数定数（16 / 15 …），二级是它下面各档小数定数
    const parents = []
    const byInt = new Map()
    list.forEach((group) => {
      const level = Number(group.level)
      const intPart = Math.floor(level)
      let parent = byInt.get(intPart)
      if (!parent) {
        parent = { id: `level-${group.level}`, label: String(intPart), icon: 'format-list-numbered', children: [] }
        byInt.set(intPart, parent)
        parents.push(parent)
      }
      parent.children.push({ id: `level-${group.level}`, label: level.toFixed(1) })
    })
    setAnchorNav(parents)
  },
  { immediate: true }
)

onUnmounted(clearAnchorNav)

onMounted(async () => {
  history.value = await loadLevelHistory()
  selectedVersion.value = versions.value[versions.value.length - 1] || ''
})
</script>

<template>
  <div class="dt-page">
    <ScrollTabs
      v-model="selectedVersion"
      :items="versions"
      class="history-tabs"
      sticky
      aria-label="选择版本"
    />

    <div class="card-container">
      <section
        v-for="group in groups"
        :id="`level-${group.level}`"
        :key="group.level"
        class="card-group"
      >
        <div class="dt-section__head">
          <h2 class="group-title dt-title-bar">{{ group.level }}</h2>
        </div>
        <div class="level-row">
          <div class="card-grid">
            <div
              v-for="chart in group.charts"
              :key="`${chart.key}-${chart.diff}`"
              class="chart-cell"
              :title="chart.name"
            >
              <levelCard
                :chart-info="[chart.key, chart.level, chart.cover, chart.diff, difColor(chart.diff), chart.name]"
                @click="openSong(chart.key)"
              />
            </div>
          </div>
        </div>
      </section>
    </div>

    <div v-if="!groups.length" class="dt-empty">这一版没有曲目</div>
  </div>
</template>

