<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'

const props = defineProps({
  // 字符串数组，或 [{ value, label }]；value 会原样回传
  items: { type: Array, required: true },
  modelValue: { type: [String, Number, Boolean], default: '' },
  // 固定在顶部：内容很长的页面滚动时切换栏仍在
  sticky: { type: Boolean, default: false },
  // 选中项的内联样式（比如比赛年份的主题色）
  tabStyle: { type: Function, default: null },
  ariaLabel: { type: String, default: '' }
})

const emit = defineEmits(['update:modelValue'])

const track = ref(null)
const overflowing = ref(false)

const normalized = computed(() =>
  props.items.map((item) =>
    item !== null && typeof item === 'object'
      ? { value: item.value, label: item.label ?? String(item.value) }
      : { value: item, label: String(item) }
  )
)

// 标签放不下时才显示两端箭头（只有几个标签的页面不需要）
const updateOverflow = () => {
  const el = track.value
  if (!el) return
  overflowing.value = el.scrollWidth - el.clientWidth > 2
}

const scrollToActive = () => {
  const el = track.value
  if (!el) return
  const active = el.querySelector('.dt-tab--active')
  if (active) active.scrollIntoView({ inline: 'center', block: 'nearest' })
}

const scrollByPage = (direction) => {
  const el = track.value
  if (!el) return
  el.scrollBy({ left: el.clientWidth * 0.7 * direction, behavior: 'smooth' })
}

watch(() => props.modelValue, () => nextTick(scrollToActive))
// 箭头出现/消失会改变轨道宽度，当前标签可能被挤出可见区，重新对准一次
watch(overflowing, () => nextTick(scrollToActive))
watch(normalized, () => nextTick(() => {
  updateOverflow()
  scrollToActive()
}))

let observer = null

onMounted(() => {
  nextTick(() => {
    updateOverflow()
    scrollToActive()
  })
  if (typeof ResizeObserver !== 'undefined' && track.value) {
    observer = new ResizeObserver(updateOverflow)
    observer.observe(track.value)
  }
})

onBeforeUnmount(() => {
  observer?.disconnect()
})
</script>

<template>
  <div class="scroll-tabs" :class="{ 'scroll-tabs--sticky': sticky }">
    <button
      v-if="overflowing"
      class="scroll-tabs__arrow"
      type="button"
      aria-label="往前翻"
      @click="scrollByPage(-1)"
    >
      <i class="mdi mdi-chevron-left"></i>
    </button>

    <div ref="track" class="dt-tabs scroll-tabs__track" :aria-label="ariaLabel || undefined">
      <button
        v-for="item in normalized"
        :key="item.value"
        class="dt-tab"
        :class="{ 'dt-tab--active': item.value === modelValue }"
        :style="tabStyle ? tabStyle(item.value) : null"
        @click="emit('update:modelValue', item.value)"
      >
        {{ item.label }}
      </button>
    </div>

    <button
      v-if="overflowing"
      class="scroll-tabs__arrow"
      type="button"
      aria-label="往后翻"
      @click="scrollByPage(1)"
    >
      <i class="mdi mdi-chevron-right"></i>
    </button>
  </div>
</template>

